"""
Handler for contact-related HubSpot operations.
"""
from typing import Any, Dict, List, Optional
import json

import mcp.types as types

from ..hubspot_client import ApiException
from .base_handler import BaseHandler

class ContactHandler(BaseHandler):
    """Handler for contact-related HubSpot tools."""

    def __init__(self, hubspot_client, faiss_manager, embedding_model):
        """Initialize the contact handler.

        Args:
            hubspot_client: HubSpot client
            faiss_manager: FAISS vector store manager
            embedding_model: Sentence transformer model
        """
        super().__init__(hubspot_client, faiss_manager, embedding_model, "contact_handler")

    def get_create_contact_schema(self) -> Dict[str, Any]:
        """Get the input schema for creating a contact.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "firstname": {"type": "string", "description": "Contact's first name"},
                "lastname": {"type": "string", "description": "Contact's last name"},
                "email": {"type": "string", "description": "Contact's email address"},
                "properties": {"type": "object", "description": "Additional contact properties"}
            },
            "required": ["firstname", "lastname"]
        }

    def get_active_contacts_schema(self) -> Dict[str, Any]:
        """Get the input schema for active contacts.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "limit": {"type": "integer", "description": "Maximum number of contacts to return (default: 10)"}
            }
        }

    def get_contact_schema(self) -> Dict[str, Any]:
        """Get the input schema for getting a contact by ID.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "contact_id": {"type": "string", "description": "HubSpot contact ID"},
                "properties": {
                    "type": "array",
                    "items": {"type": "string"},
                    "description": "Optional list of properties to retrieve. If omitted, returns all properties."
                }
            },
            "required": ["contact_id"]
        }

    def get_update_contact_schema(self) -> Dict[str, Any]:
        """Get the input schema for updating a contact by ID.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "contact_id": {"type": "string", "description": "HubSpot contact ID to update"},
                "properties": {
                    "type": "object",
                    "description": "Object containing the properties to update"
                }
            },
            "required": ["contact_id", "properties"]
        }

    def create_contact(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Create a new contact in HubSpot.

        Args:
            arguments: Tool arguments containing contact information

        Returns:
            Text response with result
        """
        self.validate_required_arguments(arguments, ["firstname", "lastname"])

        try:
            from hubspot.crm.contacts import PublicObjectSearchRequest

            firstname = arguments["firstname"]
            lastname = arguments["lastname"]
            company = arguments.get("properties", {}).get("company")

            # Search for existing contacts with same name and company
            filter_groups = [{
                "filters": [
                    {
                        "propertyName": "firstname",
                        "operator": "EQ",
                        "value": firstname
                    },
                    {
                        "propertyName": "lastname",
                        "operator": "EQ",
                        "value": lastname
                    }
                ]
            }]

            # Add company filter if provided
            if company:
                filter_groups[0]["filters"].append({
                    "propertyName": "company",
                    "operator": "EQ",
                    "value": company
                })

            search_request = PublicObjectSearchRequest(
                filter_groups=filter_groups
            )

            search_response = self.hubspot.client.crm.contacts.search_api.do_search(
                public_object_search_request=search_request
            )

            if search_response.total > 0:
                # Contact already exists
                return self.create_text_response(
                    f"Contact already exists: {search_response.results[0].to_dict()}"
                )

            # If no existing contact found, proceed with creation
            properties = {
                "firstname": firstname,
                "lastname": lastname
            }

            # Add email if provided
            if "email" in arguments:
                properties["email"] = arguments["email"]

            # Add any additional properties
            if "properties" in arguments:
                properties.update(arguments["properties"])

            # Create contact using SimplePublicObjectInputForCreate
            from hubspot.crm.contacts import SimplePublicObjectInputForCreate

            simple_public_object_input = SimplePublicObjectInputForCreate(
                properties=properties
            )

            api_response = self.hubspot.client.crm.contacts.basic_api.create(
                simple_public_object_input_for_create=simple_public_object_input
            )
            return self.create_text_response(str(api_response.to_dict()))

        except ApiException as e:
            return self.create_text_response(f"HubSpot API error: {str(e)}")
        except Exception as e:
            return self.create_text_response(f"Error: {str(e)}")

    def get_active_contacts(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get most recently active contacts from HubSpot.

        Args:
            arguments: Tool arguments containing limit parameter

        Returns:
            Text response with contact data
        """
        limit = self.get_argument_with_default(arguments, "limit", 10)

        # Ensure limit is an integer
        limit = int(limit) if limit is not None else 10

        results = self.hubspot.get_recent_contacts(limit=limit)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"limit": limit}
            self.store_in_faiss_safely(data, "contact", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing contact data: {str(e)}")

        return self.create_text_response(results)

    def get_contact(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get a specific contact by ID from HubSpot.

        Args:
            arguments: Tool arguments containing contact_id and optional properties

        Returns:
            Text response with contact data
        """
        self.validate_required_arguments(arguments, ["contact_id"])

        contact_id = arguments["contact_id"]
        properties = arguments.get("properties")

        results = self.hubspot.get_contact_by_id(contact_id, properties)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"contact_id": contact_id}
            self.store_in_faiss_safely(data, "contact", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing contact data: {str(e)}")

        return self.create_text_response(results)

    def update_contact(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Update a specific contact by ID in HubSpot.

        Args:
            arguments: Tool arguments containing contact_id and properties to update

        Returns:
            Text response with updated contact data
        """
        self.validate_required_arguments(arguments, ["contact_id", "properties"])

        contact_id = arguments["contact_id"]
        properties = arguments["properties"]

        results = self.hubspot.update_contact(contact_id, properties)

        # Store in FAISS for future reference
        try:
            data = json.loads(results)
            metadata_extras = {"contact_id": contact_id, "updated": True}
            self.store_in_faiss_safely(data, "contact", metadata_extras)
        except Exception as e:
            self.logger.error(f"Error parsing updated contact data: {str(e)}")

        return self.create_text_response(results)

"""
Error handling utilities for HubSpot API interactions.
"""
import logging
import json
import functools
from typing import Any, Callable

from hubspot.crm.contacts.exceptions import ApiException

logger = logging.getLogger('mcp_hubspot_client.error_handler')

def handle_hubspot_errors(func: Callable) -> Callable:
    """Decorator to handle HubSpot API errors consistently.

    Args:
        func: Function to wrap with error handling

    Returns:
        Wrapped function with error handling
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs) -> Any:
        try:
            return func(*args, **kwargs)
        except ApiException as e:
            logger.error(f"API Exception in {func.__name__}: {str(e)}")
            return json.dumps({"error": str(e)})
        except Exception as e:
            logger.error(f"Exception in {func.__name__}: {str(e)}")
            return json.dumps({"error": str(e)})
    return wrapper

"""
Handler for property-related HubSpot operations.
"""
from typing import Any, Dict, List, Optional
import json

import mcp.types as types

from ..hubspot_client import ApiException
from .base_handler import BaseHandler

class PropertyHandler(BaseHandler):
    """Handler for property-related HubSpot tools."""

    def __init__(self, hubspot_client, faiss_manager, embedding_model):
        """Initialize the property handler.

        Args:
            hubspot_client: HubSpot client
            faiss_manager: FAISS vector store manager
            embedding_model: Sentence transformer model
        """
        super().__init__(hubspot_client, faiss_manager, embedding_model, "property_handler")

    def get_property_schema(self) -> Dict[str, Any]:
        """Get the input schema for getting a property.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "object_type": {
                    "type": "string",
                    "enum": ["companies", "contacts"],
                    "description": "Type of CRM object"
                },
                "property_name": {
                    "type": "string",
                    "description": "Name of the property"
                }
            },
            "required": ["object_type", "property_name"]
        }

    def get_update_property_schema(self) -> Dict[str, Any]:
        """Get the input schema for updating a property.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "object_type": {
                    "type": "string",
                    "enum": ["companies", "contacts"],
                    "description": "Type of CRM object"
                },
                "property_name": {
                    "type": "string",
                    "description": "Name of the property"
                },
                "options": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "label": {"type": "string"},
                            "value": {"type": "string"},
                            "description": {"type": "string"},
                            "displayOrder": {"type": "integer"}
                        },
                        "required": ["label", "value"]
                    },
                    "description": "Array of option objects for dropdown fields"
                }
            },
            "required": ["object_type", "property_name", "options"]
        }

    def get_create_property_schema(self) -> Dict[str, Any]:
        """Get the input schema for creating a property.

        Returns:
            Schema definition dictionary
        """
        return {
            "type": "object",
            "properties": {
                "object_type": {
                    "type": "string",
                    "enum": ["companies", "contacts"],
                    "description": "Type of CRM object"
                },
                "name": {
                    "type": "string",
                    "description": "Internal name of the property"
                },
                "label": {
                    "type": "string",
                    "description": "Display label for the property"
                },
                "type": {
                    "type": "string",
                    "description": "Data type (string, number, date, enumeration, etc.)"
                },
                "fieldType": {
                    "type": "string",
                    "description": "Field type (text, textarea, select, number, date, etc.)"
                },
                "groupName": {
                    "type": "string",
                    "description": "Property group name"
                },
                "options": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "label": {"type": "string"},
                            "value": {"type": "string"},
                            "description": {"type": "string"},
                            "displayOrder": {"type": "integer"}
                        },
                        "required": ["label", "value"]
                    },
                    "description": "Array of option objects for dropdown fields"
                },
                "description": {
                    "type": "string",
                    "description": "Property description"
                }
            },
            "required": ["object_type", "name", "label", "type", "fieldType", "groupName"]
        }

    def get_property(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Get details of a specific property.

        Args:
            arguments: Tool arguments containing object_type and property_name

        Returns:
            Text response with property definition
        """
        self.validate_required_arguments(arguments, ["object_type", "property_name"])

        object_type = arguments["object_type"]
        property_name = arguments["property_name"]

        results = self.hubspot.get_property(object_type, property_name)

        return self.create_text_response(results)

    def update_property(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Update a property definition.

        Args:
            arguments: Tool arguments containing object_type, property_name, and options

        Returns:
            Text response with updated property definition
        """
        self.validate_required_arguments(arguments, ["object_type", "property_name", "options"])

        object_type = arguments["object_type"]
        property_name = arguments["property_name"]
        options = arguments["options"]

        # Extract any additional kwargs
        kwargs = {k: v for k, v in arguments.items()
                 if k not in ["object_type", "property_name", "options"]}

        results = self.hubspot.update_property(object_type, property_name, options, **kwargs)

        return self.create_text_response(results)

    def create_property(self, arguments: Optional[Dict[str, Any]]) -> List[types.TextContent]:
        """Create a new custom property.

        Args:
            arguments: Tool arguments containing property details

        Returns:
            Text response with created property definition
        """
        self.validate_required_arguments(arguments, ["object_type", "name", "label",
                                                     "type", "fieldType", "groupName"])

        object_type = arguments["object_type"]
        name = arguments["name"]
        label = arguments["label"]
        property_type = arguments["type"]
        field_type = arguments["fieldType"]
        group_name = arguments["groupName"]
        options = arguments.get("options")

        # Extract any additional kwargs
        kwargs = {k: v for k, v in arguments.items()
                 if k not in ["object_type", "name", "label", "type",
                            "fieldType", "groupName", "options"]}

        results = self.hubspot.create_property(object_type, name, label, property_type,
                                              field_type, group_name, options, **kwargs)

        return self.create_text_response(results)

